49	void FilesystemCacheLogElement::appendToBlock(MutableColumns & columns) const
50	{
51	    size_t i = 0;
52	
53	    columns[i++]->insert(DateLUT::instance().toDayNum(event_time).toUnderType());
54	    columns[i++]->insert(event_time);
55	
56	    columns[i++]->insert(query_id);
57	
58	    columns[i++]->insert(source_file_path);
59	    columns[i++]->insert(Tuple{file_segment_range.first, file_segment_range.second});
60	    columns[i++]->insert(Tuple{requested_range.first, requested_range.second});
61	    columns[i++]->insert(file_segment_size);
62	    columns[i++]->insert(typeToString(read_type));
63	    columns[i++]->insert(cache_attempted);
64	
65	    if (profile_counters)
66	    {
67	        auto * column = columns[i++].get();
68	        ProfileEvents::dumpToMapColumn(*profile_counters, column, true);
69	    }
70	    else
71	    {
72	        columns[i++]->insertDefault();
73	    }
74	
75	    columns[i++]->insert(read_buffer_id);
76	}
